#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int countCenteredSubarrays(vector<int>& nums) {
        int n = nums.size();
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
        int count = 0;
        for (int c = 0; c < n; c++) {
            int max_r = min(c, n - 1 - c);
            for (int r = 0; r <= max_r; r++) {
                long long len = 2 * r + 1;
                long long sub_sum = pref[c + r + 1] - pref[c - r];
                if (sub_sum == len * nums[c]) count++;
            }
        }
        return count;
    }
};

class Solution {
    public int countCenteredSubarrays(int[] nums) {
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
        int count = 0;
        for (int c = 0; c < n; c++) {
            int maxR = Math.min(c, n - 1 - c);
            for (int r = 0; r <= maxR; r++) {
                long len = 2 * r + 1;
                long subSum = pref[c + r + 1] - pref[c - r];
                if (subSum == len * nums[c]) count++;
            }
        }
        return count;
    }
}

var countCenteredSubarrays = function(nums) {
    const n = nums.length;
    const pref = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
    let count = 0;
    for (let c = 0; c < n; c++) {
        const maxR = Math.min(c, n - 1 - c);
        for (let r = 0; r <= maxR; r++) {
            const len = 2 * r + 1;
            const subSum = pref[c + r + 1] - pref[c - r];
            if (subSum === len * nums[c]) count++;
        }
    }
    return count;
};
